function factorial(n) {
    return n === 1
           ? 1
           : n * factorial(n - 1);
}

function gcd(a, b) {
    return b === 0 ? a : gcd(b, a % b);
}

function fib(n) {
    return n === 0
           ? 0
           : n === 1
           ? 1
           : fib(n - 1) + fib(n - 2);
}

function expt(b, n) {
    return n === 0
           ? 1
           : b * expt(b, n - 1);
}

function expt(b, n) {	  
    function expt_iter(counter, product) {
        return counter === 0
               ? product
               : expt_iter(counter - 1, b * product);
    }
    return expt_iter(n, 1);
}
